import math

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def lcm(a, b):
    if a == 0 or b == 0:
        return 0
    return abs(a * b) // gcd(a, b)

def lcm_of_range(start, end):
    """Calculates lcm(start, start+1, ..., end)"""
    if start > end:
        return 1 # Or handle error, but for positive integers this shouldn't happen
    result = start
    for i in range(start + 1, end + 1):
        result = lcm(result, i)
    return result

def check_weakly_increasing(n, max_k):
    """Checks the condition x_{k+1} > x_k for k=1 to max_k for a given n."""
    print(f"--- Analyzing n = {n} ---")
    results = []
    for k in range(1, max_k + 1):
        # x_k = lcm(k, ..., k+n-1)
        start_k = k
        end_k = k + n - 1
        x_k = lcm_of_range(start_k, end_k)

        # x_{k+1} = lcm(k+1, ..., k+n)
        start_kp1 = k + 1
        end_kp1 = k + n
        x_kp1 = lcm_of_range(start_kp1, end_kp1)

        is_increasing = x_kp1 > x_k
        results.append({
            'k': k,
            'x_k': x_k,
            'x_{k+1}': x_kp1,
            'increasing': is_increasing
        })

    print(f"Detailed results for n={n} (k=1 to {max_k}):")
    for res in results:
        print(f"k={res['k']}: x_k = {res['x_k']}, x_{res['k']+1} = {res['x_{k+1}']}. Increasing: {res['increasing']}")

    # Check for counterexamples
    counterexamples = [res for res in results if not res['increasing']]
    if counterexamples:
        print(f"!!! Counterexamples found for n={n} !!!")
        for ce in counterexamples:
            print(f"At k={ce['k']}, x_{ce['k+1']} <= x_{ce['k']}.")
    else:
        print(f"No counterexamples found for n={n} in the range k=1 to {max_k}.")


# Run checks for n=4 and n=5, up to k=10
check_weakly_increasing(4, 10)
print("\n" + "="*50 + "\n")
check_weakly_increasing(5, 10)

import math
from functools import reduce

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def lcm(a, b):
    if a == 0 or b == 0:
        return 0
    return abs(a * b) // gcd(a, b)

def lcm_list(numbers):
    if not numbers:
        return 1
    return reduce(lcm, numbers)

def calculate_x(k, n):
    # x_k = lcm(k, k+1, ..., k+n-1)
    sequence = range(k, k + n)
    return lcm_list(list(sequence))

n = 5
k_max = 20

print(f"--- Comparison for n={n} (k=1 to {k_max}) ---")
print("k | x_k | x_{k+1} | x_{k+1} <= x_k ?")
print("-" * 40)

counterexamples_found = False
for k in range(1, k_max + 1):
    x_k = calculate_x(k, n)
    x_k_plus_1 = calculate_x(k + 1, n)

    is_le = x_k_plus_1 <= x_k

    print(f"{k:2} | {x_k:12} | {x_k_plus_1:12} | {is_le}")

    if is_le:
        counterexamples_found = True

if counterexamples_found:
    print("\n--- Counterexamples Found ---")
else:
    print("\n--- No Counterexamples Found for k=1 to 20 ---")

import math
from functools import reduce

def lcm(a, b):
    """Calculates the least common multiple of two numbers."""
    if a == 0 or b == 0:
        return 0
    return abs(a * b) // math.gcd(a, b)

def list_lcm(numbers):
    """Calculates the least common multiple of a list of numbers."""
    if not numbers:
        return 1
    return reduce(lcm, numbers)

n = 5
max_k = 20
results = []

for k in range(1, max_k + 1):
    # x_k = lcm(k, k+1, ..., k+n-1) = lcm(k, k+1, k+2, k+3, k+4)
    set_k = list(range(k, k + n))
    x_k = list_lcm(set_k)

    # x_{k+1} = lcm(k+1, k+2, ..., k+n) = lcm(k+1, k+2, k+3, k+4, k+5)
    set_k_plus_1 = list(range(k + 1, k + 1 + n))
    x_k_plus_1 = list_lcm(set_k_plus_1)

    comparison = ""
    if x_k_plus_1 > x_k:
        comparison = "x_{k+1} > x_k"
    elif x_k_plus_1 < x_k:
        comparison = "x_{k+1} < x_k (Counterexample)"
    else:
        comparison = "x_{k+1} = x_k (Counterexample)"

    results.append((k, x_k, x_k_plus_1, comparison))

print("k | x_k | x_{k+1} | Comparison")
print("-" * 40)
for k, x_k, x_k_plus_1, comparison in results:
    print(f"{k:2} | {x_k:10} | {x_k_plus_1:7} | {comparison}")

counterexamples = [r for r in results if "Counterexample" in r[3]]
print("\n--- Summary ---")
if counterexamples:
    print("Counterexamples found at k values:", [k for k, _, _, _ in counterexamples])
else:
    print("No counterexamples found for k=1 to k=20.")
